  void _spawnParticles(Color color, int count, {bool sparks = false}) {
    for (int i = 0; i < count; i++) {
      particles.add(
        TrackParticle(
          x: 0.25 + rng.nextDouble() * 0.5,
          y: 0.62 + rng.nextDouble() * 0.22,
          vx: (rng.nextDouble() - 0.5) * (sparks ? 1.6 : 0.7),
          vy: (sparks ? -0.58 : -0.22) - rng.nextDouble() * 0.45,
          life: 0.35 + rng.nextDouble() * 0.35,
          color: color,
          radius: sparks ? (2.2 + rng.nextDouble() * 2.4) : (3.0 + rng.nextDouble() * 4.2),
          isSpark: sparks,
        ),
      );
    }
  }

  void _toggleErs() {
    if (startLightsTimer > 0) return;
    if (!ersToggledOn && ersCharge < 5.0) {
      _showRadio('BATERÍA ERS BAJA — FRENA PARA RECARGAR', secs: 2.0);
      return;
    }
    setState(() {
      ersToggledOn = !ersToggledOn;
    });
  }

  void _update(double dt) {
    if (raceFinished) return;

    if (radioTimer > 0) {
      radioTimer = max(0.0, radioTimer - dt);
      if (radioTimer == 0) radioMessage = '';
    }

    if (startLightsTimer > 0) {
      startLightsTimer = max(0.0, startLightsTimer - dt);
      if (mounted) setState(() {});
      return;
    }

    totalRaceTime += dt;

    for (int i = particles.length - 1; i >= 0; i--) {
      final TrackParticle p = particles[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 1.45 * dt;
      p.life -= dt;
      if (p.life <= 0) particles.removeAt(i);
    }

    _updateAiCars(dt);

    final int prevLap = currentLap;

    if (brakeHeld && ersToggledOn) {
      ersToggledOn = false;
    }

    final bool ersActive = ersToggledOn && ersCharge > 0.5 && !brakeHeld;
    if (ersActive) {
      ersCharge = max(0.0, ersCharge - 21.0 * dt);
      if (ersCharge <= 0.5) {
        ersToggledOn = false;
        _showRadio('BATERÍA ERS AGOTADA', secs: 1.8);
      }
    } else {
      final double rechargeRate = brakeHeld ? 26.0 : 6.8;
      ersCharge = min(100.0, ersCharge + rechargeRate * dt);
    }

    final bool effectivelyAccelerating = (gasHeld || autoGas || ersActive) && !brakeHeld;
    final double maxSpeed = ersActive ? 358.0 : 320.0;

    if (effectivelyAccelerating) {
      final double accel = ersActive ? 178.0 : 126.0;
      speedKmh = min(maxSpeed, speedKmh + accel * dt);
    } else if (brakeHeld) {
      speedKmh = max(0.0, speedKmh - 285.0 * dt);
    } else {
      speedKmh = max(0.0, speedKmh - 36.0 * dt);
    }

    double targetSteer = 0.0;
    if (leftHeld) targetSteer -= 1.0;
    if (rightHeld) targetSteer += 1.0;
    steerAngle += (targetSteer - steerAngle) * min(1.0, dt * 11.8);

    final double realCurve = geometry.curvatureAtProgress(lapProgress);
    horizonPan = (horizonPan - realCurve * (speedKmh / 300.0) * dt * 130.0) % 2400.0;

    final double centrifugal = realCurve * pow(speedKmh / 275.0, 1.45).toDouble() * 0.85;

    if (controlRecoveryTimer > 0) {
      controlRecoveryTimer = max(0.0, controlRecoveryTimer - dt);
    }

    final bool offTrack = carX.abs() > 1.02;
    final double steerAuthority = (offTrack ? 0.56 : 1.0) * (controlRecoveryTimer > 0 ? 0.42 : 1.0);
    final double steerForce = steerAngle * (1.60 + speedKmh / 255.0) * steerAuthority;

    lateralVel += (steerForce - centrifugal) * dt * 4.3;
    final double lateralDamping = offTrack ? 2.3 : (controlRecoveryTimer > 0 ? 1.8 : 4.9);
    lateralVel *= exp(-lateralDamping * dt);
    carX += lateralVel * dt;
    spinYaw *= exp(-4.5 * dt);

    if (offTrack) {
      speedKmh = max(48.0, speedKmh - (138.0 + speedKmh * 0.35) * dt);
      if (speedKmh > 65.0 && rng.nextDouble() < 0.45) {
        _spawnParticles(const Color(0xFFC2AA82), 2);
      }
      if (carX.abs() >= 1.52) {
        final double wallSign = carX >= 0 ? 1.0 : -1.0;
        carX = wallSign * 1.50;
        lateralVel = -wallSign * 1.75;
        spinYaw = -wallSign * 0.30;
        speedKmh = max(35.0, speedKmh * 0.48);
        hitFlash = 1.0;
        ersToggledOn = false;
        _spawnParticles(const Color(0xFFFFB300), 14, sparks: true);
        _showRadio('¡IMPACTO CONTRA EL MURO!', secs: 2.0);
      }
    }

    final double distStep = (speedKmh / 3.6) * dt;
    playerDist += distStep;

    if (hitFlash > 0) hitFlash = max(0.0, hitFlash - dt * 2.8);

    final int newLap = (playerDist / widget.circuit.lapLengthMeters).floor() + 1;
    if (newLap > prevLap) {
      final double lapDuration = totalRaceTime - lapStartTime;
      lapStartTime = totalRaceTime;
      if (lapDuration < bestLapTime) bestLapTime = lapDuration;
      if (lapDuration < fastLapTime) fastLapTime = lapDuration;

      if (newLap > totalLaps) {
        raceFinished = true;
        _timer?.cancel();
        _showFinishDialog();
        return;
      }
    }

    if (mounted) setState(() {});
  }

  void _updateAiCars(double dt) {
    for (final ai in aiDrivers) {
      final double aiProgress = (ai.trackDist % widget.circuit.lapLengthMeters) / widget.circuit.lapLengthMeters;
      final double aiCurve = geometry.curvatureAtProgress(aiProgress).abs();
      final double cornerSlowdown = (1.0 - (aiCurve * 0.14)).clamp(0.58, 1.0).toDouble();

      double pace = ai.baseSpeedKmh * cornerSlowdown;
      final double deltaToPlayer = playerDist - ai.trackDist;
      if (deltaToPlayer > 240) pace += 16.0;
      if (deltaToPlayer < -340) pace -= 12.0;

      ai.trackDist += (pace / 3.6) * dt;

      if (rng.nextDouble() < 0.015) {
        ai.targetLaneX = [-0.62, -0.20, 0.20, 0.62][rng.nextInt(4)];
      }
      ai.lateralVel *= exp(-5.0 * dt);
      ai.laneX += ((ai.targetLaneX - ai.laneX) * 1.6 + ai.lateralVel) * dt;
      ai.laneX = ai.laneX.clamp(-1.25, 1.25).toDouble();

      // Realistic Wheel-to-Wheel Collision -> Sends car flying off-track!
      final double dz = ai.trackDist - playerDist;
      if (dz > -4.6 && dz < 5.0 && (ai.laneX - carX).abs() < 0.35) {
        final double pushDir = (carX >= ai.laneX) ? 1.0 : -1.0;
        final double relImpact = (speedKmh / 200.0).clamp(0.65, 1.85).toDouble();

        lateralVel = pushDir * (2.95 * relImpact);
        spinYaw = pushDir * 0.38;
        controlRecoveryTimer = 0.70;
        speedKmh = max(50.0, speedKmh * 0.58);
        hitFlash = 1.0;
        ersToggledOn = false;

        ai.lateralVel = -pushDir * 1.95;
        carX += pushDir * 0.14;

        _spawnParticles(const Color(0xFFFFD54F), 16, sparks: true);
        _showRadio('¡CONTACTO CON ${ai.code}! FUERA DE PISTA', secs: 2.2);
      }
    }
  }

  String _formatTime(double seconds) {
    if (seconds >= 900) return '--:--.---';
    final int mins = seconds ~/ 60;
    final int secs = seconds.toInt() % 60;
    final int ms = ((seconds - seconds.floor()) * 1000).toInt();
    return '${mins.toString().padLeft(2, '0')}:${secs.toString().padLeft(2, '0')}.${ms.toString().padLeft(3, '0')}';
  }

