  @override
  Widget build(BuildContext context) {
    final int gear = (1 + (speedKmh / 41.0)).clamp(1, 8).toInt();
    final int rpm = (4800 + ((speedKmh % 41.0) / 41.0) * 7600 + (speedKmh > 20 ? 1500 : 0)).clamp(3500, 14500).toInt();
    final bool ersActive = ersToggledOn && ersCharge > 0.5 && !brakeHeld;
    final List<Map<String, Object>> board = _getMiniLeaderboard();
    final double currentLapElapsed = max(0.0, totalRaceTime - lapStartTime);

    final double aheadProgress = ((playerDist + 135.0) % widget.circuit.lapLengthMeters) / widget.circuit.lapLengthMeters;
    final double upcomingCurve = geometry.curvatureAtProgress(aheadProgress);
    String cornerWarning = '';
    if (upcomingCurve.abs() > 1.32 && speedKmh > 165.0) {
      cornerWarning = upcomingCurve > 0 ? 'CURVA DER >>' : '<< CURVA IZQ';
    }

    // Check if any rival is right behind for the side mirror radar reflections!
    bool rivalCloseLeft = false;
    bool rivalCloseRight = false;
    for (final ai in aiDrivers) {
      final double dz = playerDist - ai.trackDist;
      if (dz > 2.0 && dz < 28.0) {
        if (ai.laneX <= carX) {
          rivalCloseLeft = true;
        } else {
          rivalCloseRight = true;
        }
      }
    }

    return Scaffold(
      body: Stack(
        children: [
          Positioned.fill(
            child: CustomPaint(
              painter: F1UltraRes3DPainter(
                circuit: widget.circuit,
                geometry: geometry,
                livery: widget.livery,
                cockpitCamera: cockpitCamera,
                speedKmh: speedKmh,
                gear: gear,
                rpm: rpm,
                ersCharge: ersCharge,
                ersActive: ersActive,
                braking: brakeHeld,
                carX: carX,
                steerAngle: steerAngle,
                spinYaw: spinYaw,
                playerDist: playerDist,
                horizonPan: horizonPan,
                aiDrivers: aiDrivers,
                particles: particles,
                hitFlash: hitFlash,
                rivalCloseLeft: rivalCloseLeft,
                rivalCloseRight: rivalCloseRight,
                position: currentPosition,
                lapNumber: currentLap,
              ),
            ),
          ),

          // Top-Left F1 Broadcast HUD
          Positioned(
            top: 8,
