class RealCircuitMinimapPainter extends CustomPainter {
  final TrackGeometry geometry;
  final double playerProgress;
  final List<double> aiProgresses;
  final Color kerbColor;

  RealCircuitMinimapPainter({
    required this.geometry,
    required this.playerProgress,
    required this.aiProgresses,
    required this.kerbColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final double cx = size.width * 0.5;
    final double cy = size.height * 0.5;
    final double r = min(size.width, size.height) * 0.46;

    final Path path = Path();
    for (int i = 0; i < geometry.smoothPoints.length; i++) {
      final Offset p = geometry.smoothPoints[i];
      final double x = cx + p.dx * r;
      final double y = cy + p.dy * r;
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }
    }
    path.close();

    canvas.drawPath(
      path,
      Paint()
        ..isAntiAlias = true
        ..color = Colors.white70
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.6
        ..strokeJoin = StrokeJoin.round,
    );

    final Offset sf = geometry.pointAtProgress(0.0);
    canvas.drawCircle(Offset(cx + sf.dx * r, cy + sf.dy * r), 3.0, Paint()..isAntiAlias = true..color = kerbColor);

    final Paint aiPaint = Paint()..isAntiAlias = true..color = const Color(0xAAFF5252);
    for (final prog in aiProgresses) {
      final Offset ap = geometry.pointAtProgress(prog);
      canvas.drawCircle(Offset(cx + ap.dx * r, cy + ap.dy * r), 1.8, aiPaint);
    }

    final Offset pp = geometry.pointAtProgress(playerProgress);
    canvas.drawCircle(Offset(cx + pp.dx * r, cy + pp.dy * r), 3.9, Paint()..isAntiAlias = true..color = const Color(0xFF00E676));
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}

class F1UltraRes3DPainter extends CustomPainter {
  final CircuitInfo circuit;
  final TrackGeometry geometry;
  final TeamLivery livery;
  final bool cockpitCamera;
  final double speedKmh;
  final int gear;
  final int rpm;
  final double ersCharge;
  final bool ersActive;
  final bool braking;
  final double carX;
  final double steerAngle;
  final double spinYaw;
  final double playerDist;
  final double horizonPan;
  final List<AiDriver> aiDrivers;
  final List<TrackParticle> particles;
  final double hitFlash;
  final bool rivalCloseLeft;
  final bool rivalCloseRight;
  final int position;
  final int lapNumber;

  F1UltraRes3DPainter({
    required this.circuit,
    required this.geometry,
    required this.livery,
    required this.cockpitCamera,
    required this.speedKmh,
    required this.gear,
    required this.rpm,
    required this.ersCharge,
    required this.ersActive,
    required this.braking,
    required this.carX,
    required this.steerAngle,
    required this.spinYaw,
    required this.playerDist,
    required this.horizonPan,
    required this.aiDrivers,
    required this.particles,
    required this.hitFlash,
    required this.rivalCloseLeft,
    required this.rivalCloseRight,
    required this.position,
    required this.lapNumber,
  });

  double _curveAtWorldDist(double dist) {
    final double prog = (dist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
    return geometry.curvatureAtProgress(prog);
  }

  double _hillAtWorldDist(double dist) {
    final double prog = (dist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
    return sin(prog * pi * 4.0 + circuit.round) * circuit.hillAmp;
  }

  Offset _project(double x, double y, double z, double w, double horizonY) {
    final double fov = w * 0.60;
    final double scale = fov / max(z, 0.2);
    return Offset(w * 0.5 + x * scale, horizonY - y * scale);
  }

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width;
    final double h = size.height;
    final double horizonY = cockpitCamera ? h * 0.455 : h * 0.425;

    canvas.save();
    if (spinYaw.abs() > 0.005) {
      canvas.translate(w * 0.5, h * 0.5);
      canvas.rotate(spinYaw * 0.22);
      canvas.translate(-w * 0.5, -h * 0.5);
    }

    // 1. Ultra-Detailed Atmospheric Sky, Lens Flare, Parallax Mountains, VIP Hospitality & Grandstands
    _drawUltraEnvironment(canvas, w, h, horizonY);

    // 2. Ground with Multi-Stop Perspective Gradient
    canvas.drawRect(
      Rect.fromLTWH(0, horizonY, w, h - horizonY),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            Color.lerp(circuit.groundColor, circuit.skyBottom, 0.42)!,
            circuit.groundColor,
            Color.lerp(circuit.groundColor, Colors.black, 0.32)!,
          ],
        ).createShader(Rect.fromLTWH(0, horizonY, w, h - horizonY)),
    );

    // 3. Ultra-Dense 96-Slice 3D Track Engine with Elevation Hills, Textured Asphalt, 3D Kerbs, Catch Fencing & Braking Boards
    const double roadHalfW = 3.18;
    const double kerbOuterW = 3.60;
    const double runoffHalfW = 5.25;
    const int segCount = 96;
    const double segLen = 0.88;
    final double zOffset = playerDist % segLen;
    final double baseCamHeight = cockpitCamera ? -1.16 : -1.86;
    final double playerHill = _hillAtWorldDist(playerDist);

    final List<double> segShift = List<double>.filled(segCount + 2, 0.0);
    final List<double> segElev = List<double>.filled(segCount + 2, 0.0);
    double dxAcc = 0.0;
    double xAcc = 0.0;
    for (int i = 1; i <= segCount + 1; i++) {
      final double wd = playerDist + (i * segLen) * 2.05;
      final double k = _curveAtWorldDist(wd);
      dxAcc += k * 0.0085;
      xAcc += dxAcc;
      segShift[i] = xAcc;
      segElev[i] = (_hillAtWorldDist(wd) - playerHill) * (i / segCount);
    }

    final double camShift = carX * 2.45 + spinYaw * 1.4;
    final Path asphaltClipPath = Path();

    for (int i = segCount; i >= 1; i--) {
      final double z1 = i * segLen - zOffset;
      final double z2 = (i + 1) * segLen - zOffset;
      if (z1 <= 0.32) continue;

      final double worldDist1 = playerDist + z1 * 2.05;
      final int segIndex = (worldDist1 / (segLen * 2.2)).floor();

      final double s1 = segShift[i] - camShift;
      final double s2 = segShift[i + 1] - camShift;
      final double y1 = baseCamHeight + segElev[i];
      final double y2 = baseCamHeight + segElev[i + 1];

      final double depthT = (i / segCount).clamp(0.0, 1.0).toDouble();
      final double fogMix = pow(depthT, 2.3).toDouble() * 0.78;

      // Painted runoff area
      final Offset r1L = _project(-runoffHalfW + s1, y1, z1, w, horizonY);
      final Offset r1R = _project(runoffHalfW + s1, y1, z1, w, horizonY);
      final Offset r2L = _project(-runoffHalfW + s2, y2, z2, w, horizonY);
      final Offset r2R = _project(runoffHalfW + s2, y2, z2, w, horizonY);

      final Color runoffCol = Color.lerp(
        segIndex % 2 == 0 ? circuit.runoffColor : Color.lerp(circuit.runoffColor, Colors.black, 0.07)!,
        circuit.skyBottom,
        fogMix,
      )!;
      _drawQuad(canvas, r1L, r1R, r2R, r2L, runoffCol);

      // 3D Raised Armco / Tecpro Side Walls + FIA Catch-Fence Posts
      const double wallH = 0.74;
      final Offset w1LT = _project(-runoffHalfW + s1, y1 + wallH, z1, w, horizonY);
      final Offset w2LT = _project(-runoffHalfW + s2, y2 + wallH, z2, w, horizonY);
      final Offset w1RT = _project(runoffHalfW + s1, y1 + wallH, z1, w, horizonY);
      final Offset w2RT = _project(runoffHalfW + s2, y2 + wallH, z2, w, horizonY);

      final Color wallBase = (segIndex % 8 < 4)
          ? const Color(0xFF1A222E)
          : (segIndex % 16 < 8 ? circuit.kerbA : const Color(0xFFE8ECF2));
      final Color wallCol = Color.lerp(wallBase, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, r1L, w1LT, w2LT, r2L, wallCol);
      _drawQuad(canvas, r1R, r2R, w2RT, w1RT, wallCol);

      // Metallic catch-fencing posts above barriers
      if (i % 5 == 0 && i < segCount - 12) {
        final Offset fLT = _project(-runoffHalfW + s1, y1 + 1.85, z1, w, horizonY);
        final Offset fRT = _project(runoffHalfW + s1, y1 + 1.85, z1, w, horizonY);
        final Paint fencePaint = Paint()
          ..color = Color.lerp(const Color(0x66B0BEC5), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, 4.5 / z1);
        canvas.drawLine(w1LT, fLT, fencePaint);
        canvas.drawLine(w1RT, fRT, fencePaint);
      }

      // 3D Beveled Trapezoidal Kerbs
      final Offset k1LO = _project(-kerbOuterW + s1, y1 + 0.05, z1, w, horizonY);
      final Offset k2LO = _project(-kerbOuterW + s2, y2 + 0.05, z2, w, horizonY);
      final Offset k1RO = _project(kerbOuterW + s1, y1 + 0.05, z1, w, horizonY);
      final Offset k2RO = _project(kerbOuterW + s2, y2 + 0.05, z2, w, horizonY);
      final Offset p1L = _project(-roadHalfW + s1, y1, z1, w, horizonY);
      final Offset p1R = _project(roadHalfW + s1, y1, z1, w, horizonY);
      final Offset p2L = _project(-roadHalfW + s2, y2, z2, w, horizonY);
      final Offset p2R = _project(roadHalfW + s2, y2, z2, w, horizonY);

      final Color kerbCol = Color.lerp(segIndex % 2 == 0 ? circuit.kerbA : circuit.kerbB, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, k1LO, p1L, p2L, k2LO, kerbCol);
      _drawQuad(canvas, p1R, k1RO, k2RO, p2R, kerbCol);

      // Asphalt surface
      final bool isStartLine = (worldDist1 % circuit.lapLengthMeters) < 6.0;
      final Color rawAsphalt = isStartLine
          ? const Color(0xFFEEF2F7)
          : (segIndex % 2 == 0 ? const Color(0xFF333840) : const Color(0xFF2D3139));
      final Color asphaltCol = Color.lerp(rawAsphalt, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, p1L, p1R, p2R, p2L, asphaltCol);

      // Collect near-field road quad for high-res GPU asphalt grain overlay
      if (i < 42) {
        asphaltClipPath
          ..moveTo(p1L.dx, p1L.dy)
          ..lineTo(p1R.dx, p1R.dy)
          ..lineTo(p2R.dx, p2R.dy)
          ..lineTo(p2L.dx, p2L.dy)
          ..close();
      }

      // Rubbered racing line + sunlit/floodlight specular sheen
      if (!isStartLine) {
        final Offset g1L = _project(-1.55 + s1, y1, z1, w, horizonY);
        final Offset g1R = _project(1.55 + s1, y1, z1, w, horizonY);
        final Offset g2L = _project(-1.55 + s2, y2, z2, w, horizonY);
        final Offset g2R = _project(1.55 + s2, y2, z2, w, horizonY);
        _drawQuad(canvas, g1L, g1R, g2R, g2L, Color.fromARGB((26 * (1.0 - fogMix)).toInt(), 0, 0, 0));

        final Offset sh1L = _project(-0.48 + s1, y1, z1, w, horizonY);
        final Offset sh1R = _project(0.48 + s1, y1, z1, w, horizonY);
        final Offset sh2L = _project(-0.48 + s2, y2, z2, w, horizonY);
        final Offset sh2R = _project(0.48 + s2, y2, z2, w, horizonY);
        _drawQuad(
          canvas,
          sh1L,
          sh1R,
          sh2R,
          sh2L,
          Color.fromARGB(((circuit.nightMode ? 28 : 18) * (1.0 - fogMix)).toInt(), 255, 255, 255),
        );
      }

      // Crisp White FIA Track-Limit Lines
      final Paint linePaint = Paint()
        ..isAntiAlias = true
        ..color = Color.lerp(const Color(0xF0F5F8FC), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 4.4 / z1);
      canvas.drawLine(p1L, p2L, linePaint);
      canvas.drawLine(p1R, p2R, linePaint);

      // Environment Props
      if (i % 9 == 0 && i < segCount - 8) {
        _drawTracksideProp(canvas, -runoffHalfW - 1.7 + s1, y1, z1, w, horizonY, fogMix);
        _drawTracksideProp(canvas, runoffHalfW + 1.7 + s1, y1, z1, w, horizonY, fogMix);
      }

      // Overhead Start/Finish LED Bridge
      if (isStartLine && i > 3 && i < 60) {
        _drawStartGantry(canvas, s1, y1, z1, roadHalfW, w, horizonY, fogMix);
      }
    }

    // Apply GPU Micro-Aggregate Asphalt Grain across near-field road surface!
    if (HighResShaders.asphaltGrainShader != null) {
      canvas.save();
      canvas.clipPath(asphaltClipPath);
      final double scrollY = (playerDist * 16.0) % 96.0;
      canvas.translate(0, scrollY);
      canvas.drawRect(
        Rect.fromLTWH(0, horizonY - 96, w, h - horizonY + 192),
        Paint()..shader = HighResShaders.asphaltGrainShader..filterQuality = FilterQuality.high,
      );
      canvas.restore();
    }

    // Smooth atmospheric horizon haze strip
    canvas.drawRect(
      Rect.fromLTWH(0, horizonY - 12, w, 26),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            circuit.skyBottom.withAlpha(0),
            circuit.skyBottom.withAlpha(155),
            circuit.skyBottom.withAlpha(0),
          ],
        ).createShader(Rect.fromLTWH(0, horizonY - 12, w, 26)),
    );

    // 4. Ultra-Detailed 3D Rival F1 Cars (sorted far -> near)
    final List<AiDriver> visibleRivals = aiDrivers.where((ai) {
      final double dz = (ai.trackDist - playerDist) / 2.05;
      return dz > 1.2 && dz < 76.0;
    }).toList()
      ..sort((a, b) => b.trackDist.compareTo(a.trackDist));

    for (final ai in visibleRivals) {
      final double z = (ai.trackDist - playerDist) / 2.05;
      final int idx = (z / segLen).floor().clamp(1, segCount).toInt();
      final double rx = (ai.laneX * 2.45) + segShift[idx] - camShift;
      final double ry = baseCamHeight + segElev[idx];
      final Offset pos = _project(rx, ry, z, w, horizonY);
      final double sc = (w * 0.60) / max(z, 0.5);
      _drawRivalF1CarUltra(canvas, pos, sc, ai);
    }

    // 5. Sparks & Gravel Particles
    for (final p in particles) {
      final Offset pt = Offset(p.x * w, p.y * h);
      if (p.isSpark) {
        canvas.drawLine(
          pt,
          Offset(pt.dx - p.vx * 11, pt.dy - p.vy * 11),
          Paint()
            ..isAntiAlias = true
            ..color = p.color
            ..strokeWidth = p.radius
            ..strokeCap = StrokeCap.round,
        );
      } else {
        canvas.drawCircle(pt, p.radius, Paint()..isAntiAlias = true..color = p.color);
      }
    }

    canvas.restore();

    // 6. Ultra-High-Resolution Sculpted Cockpit OR Chase Car
    if (cockpitCamera) {
      _drawCockpitUltra(canvas, w, h);
    } else {
      _drawChaseCarUltra(canvas, w, h);
    }

    // 7. Speed Motion Blur & ERS Cyan Edge Glow
    if (speedKmh > 250 || ersActive) {
      final double alphaFrac = ((speedKmh - 245) / 110.0).clamp(0.12, 0.70).toDouble();
      final Paint streakPaint = Paint()
        ..isAntiAlias = true
        ..color = ersActive
            ? Color.fromARGB((alphaFrac * 110).toInt(), 0, 229, 255)
            : Color.fromARGB((alphaFrac * 95).toInt(), 255, 255, 255)
        ..strokeWidth = 1.7;
      for (int k = 0; k < 12; k++) {
        final double lx = (k.isEven ? 0.03 + (k * 0.009) : 0.97 - (k * 0.009)) * w;
        final double ly = ((playerDist * 28 + k * 60) % h);
        canvas.drawLine(Offset(lx, ly), Offset(lx, ly + 42), streakPaint);
      }
    }

    // 8. Subtle Cinematic Lens Vignette (adds depth & photographic contrast)
    canvas.drawRect(
      Rect.fromLTWH(0, 0, w, h),
      Paint()
        ..shader = RadialGradient(
          radius: 1.05,
          stops: const [0.65, 1.0],
          colors: const [Color(0x00000000), Color(0x55000000)],
        ).createShader(Rect.fromLTWH(0, 0, w, h)),
    );

    // 9. Collision Impact Red Vignette
    if (hitFlash > 0) {
      canvas.drawRect(
        Rect.fromLTWH(0, 0, w, h),
        Paint()
          ..shader = RadialGradient(
            radius: 0.95,
            colors: [
              const Color(0x00FF0000),
              Color.fromARGB((hitFlash * 160).toInt(), 255, 18, 18),
            ],
          ).createShader(Rect.fromLTWH(0, 0, w, h)),
      );
    }
  }

  void _drawQuad(Canvas canvas, Offset a, Offset b, Offset c, Offset d, Color color) {
    final Path p = Path()
      ..moveTo(a.dx, a.dy)
      ..lineTo(b.dx, b.dy)
      ..lineTo(c.dx, c.dy)
      ..lineTo(d.dx, d.dy)
      ..close();
    canvas.drawPath(p, Paint()..isAntiAlias = true..color = color);
  }

  void _drawUltraEnvironment(Canvas canvas, double w, double h, double horizonY) {
    final Color skyMid = Color.lerp(circuit.skyTop, circuit.skyBottom, 0.56)!;
    canvas.drawRect(
      Rect.fromLTWH(0, 0, w, horizonY),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.52, 1.0],
          colors: [circuit.skyTop, skyMid, circuit.skyBottom],
        ).createShader(Rect.fromLTWH(0, 0, w, horizonY)),
    );

    // Volumetric Sun / Moon + Subtle Anamorphic Lens Flare
    final double sunX = ((w * 0.72 + horizonPan * 0.14) % (w * 1.4)) - w * 0.2;
    final Offset sunCenter = Offset(sunX, horizonY * 0.40);
    canvas.drawCircle(
      sunCenter,
      circuit.nightMode ? 38 : 110,
      Paint()
        ..color = circuit.nightMode ? const Color(0x38D8ECFF) : const Color(0x58FFD28A)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 28),
    );
    canvas.drawCircle(
      sunCenter,
      circuit.nightMode ? 14 : 26,
      Paint()..color = circuit.nightMode ? const Color(0xDDEEF6FF) : const Color(0xEEFFFBE8),
    );
    if (!circuit.nightMode) {
      // Soft horizontal anamorphic sun streak
      canvas.drawRect(
        Rect.fromCenter(center: sunCenter, width: w * 0.42, height: 4.0),
        Paint()
          ..color = const Color(0x28FFF2CC)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6),
      );
    }

    if (circuit.nightMode) {
      final Paint starPaint = Paint()..color = const Color(0xAAFFFFFF);
      for (int s = 0; s < 32; s++) {
        final double sx = ((s * 97.0 + horizonPan * 0.08) % w + w) % w;
        final double sy = (s * 27.0) % (horizonY * 0.65);
        canvas.drawCircle(Offset(sx, sy), (s % 3 == 0) ? 1.4 : 0.9, starPaint);
      }
    } else {
      final Paint cloudPaint = Paint()
        ..color = const Color(0x3DFFFFFF)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 14);
      for (int c = 0; c < 7; c++) {
        final double cx = ((c * 220.0 + horizonPan * 0.18) % (w + 280)) - 140;
        final double cy = horizonY * (0.20 + (c % 3) * 0.16);
        canvas.drawOval(Rect.fromCenter(center: Offset(cx, cy), width: 190, height: 30), cloudPaint);
      }
    }

    // Two-Layer Parallax Distant Mountains / City Skyline
    final Path backRange = Path()..moveTo(0, horizonY);
    for (double x = 0; x <= w + 40; x += 32) {
      final double wx = x - horizonPan * 0.25;
      final double pk = 22.0 + sin(wx * 0.009) * 20.0 + cos(wx * 0.023) * 11.0;
      backRange.lineTo(x, horizonY - pk);
    }
    backRange.lineTo(w, horizonY);
    backRange.close();
    canvas.drawPath(
      backRange,
      Paint()..color = Color.lerp(circuit.nightMode ? const Color(0xFF0A1020) : const Color(0xFF33455C), circuit.skyBottom, 0.45)!,
    );

    final Path frontRange = Path()..moveTo(0, horizonY);
    for (double x = 0; x <= w + 40; x += 34) {
      final double wx = x - horizonPan * 0.38;
      final double pk = circuit.propStyle == PropStyle.skyline
          ? (20.0 + ((wx ~/ 40).abs() % 6) * 14.0)
          : (14.0 + sin(wx * 0.015 + 1.2) * 15.0 + cos(wx * 0.032) * 8.0);
      frontRange.lineTo(x, horizonY - pk);
    }
    frontRange.lineTo(w, horizonY);
    frontRange.close();
    canvas.drawPath(
      frontRange,
      Paint()..color = Color.lerp(circuit.nightMode ? const Color(0xFF10172B) : const Color(0xFF243345), circuit.skyBottom, 0.25)!,
    );

    // Multi-Tier Architectural Main Grandstand + Glass VIP Paddock Club
    final double gsX = ((w * 0.03 + horizonPan * 0.52) % (w * 1.6)) - w * 0.3;
    final double gsW = w * 0.60;
    final double gsTop = horizonY - 50;
    canvas.drawRect(
      Rect.fromLTWH(gsX, gsTop, gsW, 50),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: circuit.nightMode
              ? const [Color(0xFF1C263D), Color(0xFF0C111C)]
              : const [Color(0xFF535E70), Color(0xFF252B36)],
        ).createShader(Rect.fromLTWH(gsX, gsTop, gsW, 50)),
    );
    // VIP Glass Balcony Band
    canvas.drawRect(
      Rect.fromLTWH(gsX + 4, gsTop + 3, gsW - 8, 9),
      Paint()..color = circuit.nightMode ? const Color(0x9940C4FF) : const Color(0x66B3E5FC),
    );
    // Curved Roof Canopy
    canvas.drawRect(
      Rect.fromLTWH(gsX - 12, gsTop - 8, gsW + 24, 9),
      Paint()..color = circuit.nightMode ? const Color(0xFF314061) : const Color(0xFF8C98A8),
    );
    // Spectator Tier Lines & Subtle Colored Crowd Dots
    for (int row = 0; row < 4; row++) {
      final double ry = gsTop + 17 + row * 8.0;
      canvas.drawLine(
        Offset(gsX + 6, ry),
        Offset(gsX + gsW - 6, ry),
        Paint()..color = const Color(0x40FFFFFF)..strokeWidth = 1.6,
      );
    }
    final Paint pillarPaint = Paint()..color = const Color(0xFF1A1F29)..strokeWidth = 3.2;
    for (int p = 0; p <= 7; p++) {
      final double px = gsX + (gsW / 7) * p;
      canvas.drawLine(Offset(px, gsTop), Offset(px, horizonY), pillarPaint);
    }
  }

  void _drawStartGantry(
    Canvas canvas,
    double s1,
    double y1,
    double z1,
    double roadHalfW,
    double w,
    double horizonY,
    double fogMix,
  ) {
    final Offset bL = _project(-roadHalfW - 0.85 + s1, y1, z1, w, horizonY);
    final Offset bR = _project(roadHalfW + 0.85 + s1, y1, z1, w, horizonY);
    final Offset tL = _project(-roadHalfW - 0.85 + s1, y1 + 3.5, z1, w, horizonY);
    final Offset tR = _project(roadHalfW + 0.85 + s1, y1 + 3.5, z1, w, horizonY);
    final double beamH = max(5.0, 58.0 / z1);

    final Paint postPaint = Paint()
      ..isAntiAlias = true
      ..color = Color.lerp(const Color(0xFF1B212C), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(3.0, 26.0 / z1);
    canvas.drawLine(bL, tL, postPaint);
    canvas.drawLine(bR, tR, postPaint);

    final Rect bridge = Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tR.dy + beamH * 0.5);
    canvas.drawRect(bridge, Paint()..color = Color.lerp(const Color(0xFF101520), circuit.skyBottom, fogMix)!);
    canvas.drawRect(
      Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tL.dy - beamH * 0.22),
      Paint()..color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix)!,
    );
  }

  void _drawTracksideProp(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fogMix,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY);
    final Offset top = _project(x, y1 + 3.9, z, w, horizonY);
    final double ph = max(8.0, base.dy - top.dy);
    final double pw = max(6.0, ph * 0.52);

    if (circuit.propStyle == PropStyle.palms) {
      canvas.drawLine(
        base,
        top,
        Paint()
          ..isAntiAlias = true
          ..color = Color.lerp(const Color(0xFF5D4037), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(2.2, pw * 0.16),
      );
      final Paint frondPaint = Paint()
        ..isAntiAlias = true
        ..color = Color.lerp(circuit.nightMode ? const Color(0xFF1C4F30) : const Color(0xFF2B6E33), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.0, pw * 0.14)
        ..strokeCap = StrokeCap.round;
      for (int a = 0; a < 7; a++) {
        final double ang = -pi + (a * pi / 6);
        canvas.drawLine(top, Offset(top.dx + cos(ang) * pw * 0.95, top.dy + sin(ang) * pw * 0.45 + 4), frondPaint);
      }
    } else if (circuit.propStyle == PropStyle.skyline) {
      final Rect bldg = Rect.fromLTWH(top.dx - pw * 0.65, top.dy - ph * 0.35, pw * 1.3, ph * 1.35);
      canvas.drawRect(
        bldg,
        Paint()..color = Color.lerp(circuit.nightMode ? const Color(0xFF161E33) : const Color(0xFF384257), circuit.skyBottom, fogMix)!,
      );
      if (pw > 14) {
        final Paint win = Paint()..color = circuit.nightMode ? const Color(0xCC00E5FF) : const Color(0x66FFF0A6);
        for (int r = 0; r < 3; r++) {
          canvas.drawRect(Rect.fromLTWH(bldg.left + pw * 0.2, bldg.top + ph * (0.2 + r * 0.25), pw * 0.9, ph * 0.09), win);
        }
      }
    } else if (circuit.propStyle == PropStyle.trees) {
      canvas.drawLine(
        base,
        Offset(top.dx, base.dy - ph * 0.42),
        Paint()..color = Color.lerp(const Color(0xFF4E342E), circuit.skyBottom, fogMix)!..strokeWidth = max(2.2, pw * 0.18),
      );
      final Color leafDark = Color.lerp(const Color(0xFF18441E), circuit.skyBottom, fogMix)!;
      final Color leafLight = Color.lerp(const Color(0xFF35783A), circuit.skyBottom, fogMix)!;
      canvas.drawCircle(Offset(top.dx, base.dy - ph * 0.65), pw * 0.56, Paint()..isAntiAlias = true..color = leafDark);
      canvas.drawCircle(Offset(top.dx - pw * 0.15, base.dy - ph * 0.72), pw * 0.36, Paint()..isAntiAlias = true..color = leafLight);
    } else {
      canvas.drawLine(
        base,
        top,
        Paint()..color = Color.lerp(const Color(0xFF90A4AE), circuit.skyBottom, fogMix)!..strokeWidth = max(1.8, pw * 0.12),
      );
      if (circuit.nightMode) {
        canvas.drawCircle(
          top,
          max(5.0, pw * 0.48),
          Paint()
            ..color = const Color(0x58FFFDE7)
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 9),
        );
        canvas.drawCircle(top, max(2.5, pw * 0.18), Paint()..color = const Color(0xFFFFFFFF));
      }
    }
  }

  void _drawRivalF1CarUltra(Canvas canvas, Offset pos, double sc, AiDriver ai) {
    final double cw = (sc * 1.40).clamp(11.0, 240.0).toDouble();
    final double ch = (sc * 0.61).clamp(5.5, 105.0).toDouble();

    // 1. Soft Ambient Occlusion Ground Shadow
    canvas.drawOval(
      Rect.fromCenter(center: Offset(pos.dx, pos.dy + ch * 0.06), width: cw * 1.58, height: ch * 0.42),
      Paint()
        ..color = const Color(0xC2000000)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 5),
    );

    // 2. Sculpted Wide Rear Slick Tires + Pirelli Red Sidewall Ring
    final RRect tireL = RRect.fromRectAndRadius(
      Rect.fromLTWH(pos.dx - cw * 0.74, pos.dy - ch * 0.96, cw * 0.29, ch * 0.96),
      Radius.circular(cw * 0.055),
    );
    final RRect tireR = RRect.fromRectAndRadius(
      Rect.fromLTWH(pos.dx + cw * 0.45, pos.dy - ch * 0.96, cw * 0.29, ch * 0.96),
      Radius.circular(cw * 0.055),
    );
    canvas.drawRRect(
      tireL,
      Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          colors: [Color(0xFF0A0C10), Color(0xFF333945), Color(0xFF0E1015)],
        ).createShader(tireL.outerRect),
    );
    canvas.drawRRect(
      tireR,
      Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          colors: [Color(0xFF0E1015), Color(0xFF333945), Color(0xFF0A0C10)],
        ).createShader(tireR.outerRect),
    );

    // 3. Rear Suspension Wishbones + Carbon Venturi Diffuser + Beam Wing
    final Paint suspP = Paint()..color = const Color(0xFF1A1E26)..strokeWidth = max(1.2, ch * 0.08);
    canvas.drawLine(Offset(pos.dx - cw * 0.45, pos.dy - ch * 0.50), Offset(pos.dx - cw * 0.25, pos.dy - ch * 0.46), suspP);
    canvas.drawLine(Offset(pos.dx + cw * 0.45, pos.dy - ch * 0.50), Offset(pos.dx + cw * 0.25, pos.dy - ch * 0.46), suspP);

    final Rect diffRect = Rect.fromLTWH(pos.dx - cw * 0.40, pos.dy - ch * 0.36, cw * 0.80, ch * 0.36);
    canvas.drawRect(diffRect, Paint()..color = const Color(0xFF12151C));
    if (cw > 34) {
      final Paint strakePaint = Paint()..color = const Color(0xFF343C4C)..strokeWidth = max(1.0, cw * 0.015);
      canvas.drawLine(Offset(pos.dx - cw * 0.22, diffRect.top), Offset(pos.dx - cw * 0.22, diffRect.bottom), strakePaint);
      canvas.drawLine(Offset(pos.dx + cw * 0.22, diffRect.top), Offset(pos.dx + cw * 0.22, diffRect.bottom), strakePaint);
    }

    // 4. Sculpted Sidepods & Coke-Bottle Engine Cover with Glossy Metallic Gradient
    final Path chassis = Path()
      ..moveTo(pos.dx - cw * 0.47, pos.dy - ch * 0.30)
      ..lineTo(pos.dx - cw * 0.35, pos.dy - ch * 0.99)
      ..quadraticBezierTo(pos.dx, pos.dy - ch * 1.22, pos.dx + cw * 0.35, pos.dy - ch * 0.99)
      ..lineTo(pos.dx + cw * 0.47, pos.dy - ch * 0.30)
      ..close();
    canvas.drawPath(
      chassis,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [ai.bodyHighlight, ai.bodyColor, const Color(0xFF0A0C10)],
        ).createShader(Rect.fromLTWH(pos.dx - cw * 0.47, pos.dy - ch * 1.22, cw * 0.94, ch * 0.95)),
    );

    // 5. Driver Helmet + Visor + Airbox + T-Cam
    canvas.drawCircle(Offset(pos.dx, pos.dy - ch * 1.18), cw * 0.105, Paint()..isAntiAlias = true..color = ai.helmetColor);
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx - cw * 0.09, pos.dy - ch * 1.48, cw * 0.18, ch * 0.34), Radius.circular(cw * 0.04)),
      Paint()..isAntiAlias = true..color = ai.bodyColor,
    );
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.14, pos.dy - ch * 1.54, cw * 0.28, ch * 0.06), Paint()..color = const Color(0xFF171A21));

    // 6. Dual-Element Rear Wing + Swan-Neck Pillar + Endplates
    final Rect wingTop = Rect.fromLTWH(pos.dx - cw * 0.49, pos.dy - ch * 1.30, cw * 0.98, ch * 0.21);
    canvas.drawRect(wingTop, Paint()..color = ai.wingColor);
    canvas.drawLine(
      Offset(wingTop.left + 2, wingTop.center.dy),
      Offset(wingTop.right - 2, wingTop.center.dy),
      Paint()..color = const Color(0x99000000)..strokeWidth = max(1.0, ch * 0.045),
    );
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.52, pos.dy - ch * 1.34, cw * 0.06, ch * 0.54), Paint()..color = const Color(0xFF191D26));
    canvas.drawRect(Rect.fromLTWH(pos.dx + cw * 0.46, pos.dy - ch * 1.34, cw * 0.06, ch * 0.54), Paint()..color = const Color(0xFF191D26));

    // 7. Glowing FIA Rain Light
    final Rect lightRect = Rect.fromLTWH(pos.dx - cw * 0.04, pos.dy - ch * 0.48, cw * 0.08, ch * 0.20);
    canvas.drawRect(
      lightRect,
      Paint()
        ..color = const Color(0xBBFF1744)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4),
    );
    canvas.drawRect(lightRect, Paint()..color = const Color(0xFFFF4565));

    // 8. Broadcast 3-Letter Tag
    if (cw > 24) {
      final double fz = (cw * 0.13).clamp(9.0, 13.0).toDouble();
      final TextPainter tp = TextPainter(
        text: TextSpan(
          text: ai.code,
          style: TextStyle(color: Colors.white, fontSize: fz, fontWeight: FontWeight.w900, letterSpacing: 0.5),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      final double bx = pos.dx - tp.width * 0.5 - 5;
      final double by = pos.dy - ch * 1.68 - tp.height;
      canvas.drawRRect(
        RRect.fromRectAndRadius(Rect.fromLTWH(bx, by - 1, tp.width + 10, tp.height + 2), const Radius.circular(4)),
        Paint()..color = const Color(0xBB080C14),
      );
      canvas.drawRect(Rect.fromLTWH(bx, by - 1, 2.6, tp.height + 2), Paint()..color = ai.bodyColor);
      tp.paint(canvas, Offset(bx + 5, by));
    }
  }

  void _drawCockpitUltra(Canvas canvas, double w, double h) {
    final double cx = w * 0.5;
    final double offTrackShake = carX.abs() > 1.02 ? (sin(playerDist * 2.6) * 4.5) : 0.0;
    final double vib = sin(playerDist * 0.9) * (speedKmh / 320.0) * 1.5 + offTrackShake;

    final Paint carbonPaint = HighResShaders.carbonShader != null
        ? (Paint()..isAntiAlias = true..shader = HighResShaders.carbonShader..filterQuality = FilterQuality.high)
        : (Paint()..isAntiAlias = true..color = const Color(0xFF161920));

    // 1. Subtle Aerodynamic Front Wing Tips visible ahead of tires
    final double wheelShift = steerAngle * 16.0;
    final Paint wingTipPaint = Paint()
      ..isAntiAlias = true
      ..shader = LinearGradient(
        colors: [livery.primaryLight, livery.primaryDark],
      ).createShader(Rect.fromLTWH(0, h * 0.58, w, 40));
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.08 + wheelShift * 0.6, h * 0.60 + vib, w * 0.09, 10), const Radius.circular(3)),
      wingTipPaint,
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.83 + wheelShift * 0.6, h * 0.60 + vib, w * 0.09, 10), const Radius.circular(3)),
      wingTipPaint,
    );

    // 2. Ultra-Detailed 3D Front Slick Tires + Hot Ceramic Brake Glow
    _drawFrontTireUltra(canvas, Offset(w * 0.175 + wheelShift, h * 0.72 + vib), w * 0.155, h * 0.31, true);
    _drawFrontTireUltra(canvas, Offset(w * 0.825 + wheelShift, h * 0.72 + vib), w * 0.155, h * 0.31, false);

    // 3. Multi-Link Carbon Suspension Wishbones + Titanium Pushrod
    final Paint suspUpper = Paint()..isAntiAlias = true..color = const Color(0xFF1E232D)..strokeWidth = 6.5..strokeCap = StrokeCap.round;
    final Paint suspLower = Paint()..isAntiAlias = true..color = const Color(0xFF101319)..strokeWidth = 8.2..strokeCap = StrokeCap.round;
    final Paint pushrod = Paint()..isAntiAlias = true..color = const Color(0xFF525E73)..strokeWidth = 3.2..strokeCap = StrokeCap.round;

    canvas.drawLine(Offset(w * 0.22 + wheelShift * 0.5, h * 0.68 + vib), Offset(w * 0.38, h * 0.74 + vib), suspUpper);
    canvas.drawLine(Offset(w * 0.23 + wheelShift * 0.5, h * 0.77 + vib), Offset(w * 0.40, h * 0.80 + vib), suspLower);
    canvas.drawLine(Offset(w * 0.24 + wheelShift * 0.5, h * 0.75 + vib), Offset(w * 0.39, h * 0.70 + vib), pushrod);

    canvas.drawLine(Offset(w * 0.78 + wheelShift * 0.5, h * 0.68 + vib), Offset(w * 0.62, h * 0.74 + vib), suspUpper);
    canvas.drawLine(Offset(w * 0.77 + wheelShift * 0.5, h * 0.77 + vib), Offset(w * 0.60, h * 0.80 + vib), suspLower);
    canvas.drawLine(Offset(w * 0.76 + wheelShift * 0.5, h * 0.75 + vib), Offset(w * 0.61, h * 0.70 + vib), pushrod);

    // 4. Sculpted Glossy Clearcoat Monocoque + Aerodynamic Mirrors with Live Rival Radar!
    final Path cowling = Path()
      ..moveTo(0, h * 0.70 + vib)
      ..quadraticBezierTo(w * 0.20, h * 0.61 + vib, w * 0.36, h * 0.73 + vib)
      ..lineTo(w * 0.64, h * 0.73 + vib)
      ..quadraticBezierTo(w * 0.80, h * 0.61 + vib, w, h * 0.70 + vib)
      ..lineTo(w, h)
      ..lineTo(0, h)
      ..close();
    canvas.drawPath(
      cowling,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.20, 0.56, 1.0],
          colors: [livery.primaryLight, livery.primary, livery.primaryDark, const Color(0xFF090B0F)],
        ).createShader(Rect.fromLTWH(0, h * 0.61, w, h * 0.39)),
    );

    // Specular clearcoat shoulder highlight
    canvas.drawPath(
      Path()
        ..moveTo(0, h * 0.70 + vib)
        ..quadraticBezierTo(w * 0.20, h * 0.61 + vib, w * 0.36, h * 0.73 + vib)
        ..lineTo(w * 0.64, h * 0.73 + vib)
        ..quadraticBezierTo(w * 0.80, h * 0.61 + vib, w, h * 0.70 + vib),
      Paint()
        ..isAntiAlias = true
        ..color = const Color(0x99FFFFFF)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.6,
    );

    // Racing stripe accent on nose shoulders
    canvas.drawPath(
      Path()
        ..moveTo(w * 0.04, h * 0.715 + vib)
        ..quadraticBezierTo(w * 0.20, h * 0.645 + vib, w * 0.34, h * 0.745 + vib),
      Paint()
        ..isAntiAlias = true
        ..color = livery.secondary.withAlpha(200)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 3.0,
    );
    canvas.drawPath(
      Path()
        ..moveTo(w * 0.96, h * 0.715 + vib)
        ..quadraticBezierTo(w * 0.80, h * 0.645 + vib, w * 0.66, h * 0.745 + vib),
      Paint()
        ..isAntiAlias = true
        ..color = livery.secondary.withAlpha(200)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 3.0,
    );

    _drawSideMirrorUltra(canvas, Offset(w * 0.26, h * 0.655 + vib), true, rivalCloseLeft);
    _drawSideMirrorUltra(canvas, Offset(w * 0.74, h * 0.655 + vib), false, rivalCloseRight);

    // Woven Carbon-Fiber Cockpit Tub
    final Path tub = Path()
      ..moveTo(w * 0.23, h * 0.75 + vib)
      ..lineTo(w * 0.77, h * 0.75 + vib)
      ..lineTo(w * 0.84, h)
      ..lineTo(w * 0.16, h)
      ..close();
    canvas.drawPath(tub, carbonPaint);
    canvas.drawPath(
      tub,
      Paint()
        ..shader = const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color(0xCC000000), Color(0x38000000)],
        ).createShader(Rect.fromLTWH(w * 0.16, h * 0.75, w * 0.68, h * 0.25)),
    );

    // 5. Sculpted 3D Cylindrical Titanium Halo (Arch + Pillar + Carbon Underside)
    final Path haloArch = Path()
      ..moveTo(0, 0)
      ..lineTo(w, 0)
      ..lineTo(w, h * 0.15)
      ..quadraticBezierTo(cx, h * 0.015, 0, h * 0.15)
      ..close();
    canvas.drawPath(
      haloArch,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [const Color(0xFF090B10), livery.primaryDark, livery.primary],
        ).createShader(Rect.fromLTWH(0, 0, w, h * 0.16)),
    );

    final Path pillar = Path()
      ..moveTo(cx - 26, h * 0.045)
      ..lineTo(cx + 26, h * 0.045)
      ..lineTo(cx + 12, h * 0.735 + vib)
      ..lineTo(cx - 12, h * 0.735 + vib)
      ..close();
    canvas.drawPath(
      pillar,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          stops: const [0.0, 0.26, 0.50, 0.78, 1.0],
          colors: [
            const Color(0xFF0A0C10),
            livery.primaryDark,
            livery.primaryLight,
            livery.primaryDark,
            const Color(0xFF080A0E),
          ],
        ).createShader(Rect.fromLTWH(cx - 26, 0, 52, h * 0.74)),
    );

    // 6. Pro-Grade Butterfly F1 Steering Wheel + Contoured Gloved Hands
    _drawButterflyWheelUltra(canvas, cx, h * 0.855 + vib, w, h, carbonPaint);
  }

  void _drawSideMirrorUltra(Canvas canvas, Offset pos, bool isLeft, bool rivalBehind) {
    final double dir = isLeft ? -1.0 : 1.0;
    canvas.drawLine(
      Offset(pos.dx - dir * 10, pos.dy + 17),
      Offset(pos.dx, pos.dy + 4),
      Paint()..isAntiAlias = true..color = const Color(0xFF141720)..strokeWidth = 4.6,
    );
    final RRect shell = RRect.fromRectAndRadius(
      Rect.fromCenter(center: pos, width: 48, height: 19),
      const Radius.circular(9),
    );
    canvas.drawRRect(
      shell,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [livery.primaryLight, livery.primaryDark],
        ).createShader(shell.outerRect),
    );
    final Rect glass = Rect.fromCenter(center: Offset(pos.dx, pos.dy + 1), width: 38, height: 12);
    canvas.drawRRect(
      RRect.fromRectAndRadius(glass, const Radius.circular(5)),
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [circuit.skyTop, circuit.skyBottom, const Color(0xFF282D38)],
        ).createShader(glass),
    );
    if (rivalBehind) {
      // Reflected rival car silhouette dot in the side mirror!
      canvas.drawCircle(Offset(pos.dx, pos.dy + 3), 3.2, Paint()..color = const Color(0xFFFF1744));
    }
  }

  void _drawFrontTireUltra(Canvas canvas, Offset center, double tw, double th, bool isLeft) {
    final RRect tireRect = RRect.fromRectAndRadius(
      Rect.fromCenter(center: center, width: tw, height: th),
      const Radius.circular(24),
    );

    // Glowing ceramic brake disc under heavy braking
    if (braking && speedKmh > 55) {
      canvas.drawCircle(
        Offset(center.dx + (isLeft ? tw * 0.46 : -tw * 0.46), center.dy),
        tw * 0.26,
        Paint()
          ..color = const Color(0xCCFF3D00)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 12),
      );
    }

    // Cylindrical rubber shading with subtle asphalt reflection
    canvas.drawRRect(
      tireRect,
      Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          stops: [0.0, 0.20, 0.48, 0.76, 1.0],
          colors: [
            Color(0xFF08090C),
            Color(0xFF222730),
            Color(0xFF3E4554),
            Color(0xFF1D222B),
            Color(0xFF08090C),
          ],
        ).createShader(tireRect.outerRect),
    );

    // Rotating rubber grain bands
    if (speedKmh > 5) {
      final double phase = (playerDist * 0.72) % 1.0;
      final Paint bandPaint = Paint()..color = const Color(0x2E000000)..strokeWidth = 4.2;
      for (int b = 0; b < 5; b++) {
        final double yFrac = ((b * 0.2 + phase) % 1.0) - 0.5;
        final double yy = center.dy + yFrac * th * 0.86;
        canvas.drawLine(Offset(center.dx - tw * 0.36, yy), Offset(center.dx + tw * 0.36, yy), bandPaint);
      }
    }

    // Crisp Pirelli P-Zero Red Sidewall Ring
    canvas.drawArc(
      Rect.fromCenter(
        center: Offset(center.dx + (isLeft ? tw * 0.23 : -tw * 0.23), center.dy),
        width: tw * 0.47,
        height: th * 0.70,
      ),
      -pi * 0.37,
      pi * 0.74,
      false,
      Paint()
        ..isAntiAlias = true
        ..color = const Color(0xFFE10600)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 4.0,
    );
  }

  void _drawButterflyWheelUltra(
    Canvas canvas,
    double cx,
    double cy,
    double w,
    double h,
    Paint carbonPaint,
  ) {
    canvas.save();
    canvas.translate(cx, cy);
    canvas.rotate(steerAngle * 0.45 + spinYaw * 0.5);

    final double swW = (w * 0.39).clamp(225.0, 350.0).toDouble();
    final double swH = (h * 0.32).clamp(124.0, 188.0).toDouble();

    // Soft ambient shadow
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromCenter(center: const Offset(0, 9), width: swW, height: swH), const Radius.circular(24)),
      Paint()
        ..color = const Color(0xCC000000)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 14),
    );

    // Sculpted Butterfly Wheel Frame
    final Path wheelShape = Path()
      ..moveTo(-swW * 0.42, -swH * 0.47)
      ..lineTo(-swW * 0.24, -swH * 0.47)
      ..lineTo(-swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.24, -swH * 0.47)
      ..lineTo(swW * 0.42, -swH * 0.47)
      ..quadraticBezierTo(swW * 0.52, -swH * 0.45, swW * 0.50, -swH * 0.12)
      ..lineTo(swW * 0.47, swH * 0.37)
      ..quadraticBezierTo(swW * 0.44, swH * 0.49, swW * 0.24, swH * 0.47)
      ..lineTo(-swW * 0.24, swH * 0.47)
      ..quadraticBezierTo(-swW * 0.44, swH * 0.49, -swW * 0.47, swH * 0.37)
      ..lineTo(-swW * 0.50, -swH * 0.12)
      ..quadraticBezierTo(-swW * 0.52, -swH * 0.45, -swW * 0.42, -swH * 0.47)
      ..close();

    canvas.drawPath(wheelShape, carbonPaint);
    canvas.drawPath(
      wheelShape,
      Paint()
        ..isAntiAlias = true
        ..color = const Color(0xFF556278)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.4,
    );

    // 15 Progressive Blooming RPM Shift LEDs
    final double rpmRatio = ((rpm - 5800) / 8400.0).clamp(0.0, 1.0).toDouble();
    const int ledCount = 15;
    for (int i = 0; i < ledCount; i++) {
      final bool lit = (i / ledCount) < rpmRatio;
      final Color ledColor = i < 5
          ? const Color(0xFF00E676)
          : (i < 10 ? const Color(0xFFFF1744) : const Color(0xFF2979FF));
      final double lx = -swW * 0.22 + (i * (swW * 0.44 / (ledCount - 1)));
      if (lit) {
        canvas.drawCircle(
          Offset(lx, -swH * 0.29),
          5.4,
          Paint()
            ..color = ledColor.withAlpha(155)
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4.5),
        );
      }
      canvas.drawCircle(Offset(lx, -swH * 0.29), 2.8, Paint()..isAntiAlias = true..color = lit ? ledColor : const Color(0xFF202530));
    }

    // Recessed Anti-Glare OLED Telemetry Screen
    final Rect lcdRect = Rect.fromCenter(center: Offset(0, -swH * 0.01), width: swW * 0.45, height: swH * 0.45);
    canvas.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)), Paint()..color = const Color(0xFF04060A));
    canvas.drawRRect(
      RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)),
      Paint()
        ..isAntiAlias = true
        ..color = ersActive ? const Color(0xFF00E5FF) : const Color(0xFF3E4C63)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.7,
    );

    // OLED Telemetry Zones: Gear, Speed, Position, Lap, RPM, ERS Bar
    _drawCenteredText(canvas, '$gear', Offset(0, -swH * 0.025), swH * 0.225, Colors.white, FontWeight.w900);
    _drawCenteredText(canvas, '${speedKmh.toInt()}', Offset(-swW * 0.145, -swH * 0.13), swH * 0.102, const Color(0xFF00E676), FontWeight.w900);
    _drawCenteredText(canvas, 'P$position', Offset(swW * 0.145, -swH * 0.13), swH * 0.09, const Color(0xFFFFD54F), FontWeight.w900);
    _drawCenteredText(canvas, 'L$lapNumber/5', Offset(swW * 0.145, swH * 0.04), swH * 0.072, Colors.white70, FontWeight.bold);
    _drawCenteredText(
      canvas,
      ersActive ? 'ERS BOOST' : '$rpm RPM',
      Offset(0, swH * 0.11),
      swH * 0.075,
      ersActive ? const Color(0xFF00E5FF) : const Color(0xFF94A3B8),
      FontWeight.bold,
    );

    final double barW = lcdRect.width - 12;
    canvas.drawRect(Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 6, barW, 3.4), Paint()..color = const Color(0xFF1E293B));
    canvas.drawRect(
      Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 6, barW * (ersCharge / 100.0), 3.4),
      Paint()..color = ersActive ? const Color(0xFF00E5FF) : const Color(0xFFFFD600),
    );

    // 3 Anodized Knurled Rotary Dials with Brushed Metal Bezels
    const List<Color> knobColors = [Color(0xFFE53935), Color(0xFF43A047), Color(0xFFFFB300)];
    for (int k = 0; k < 3; k++) {
      final double kx = (k - 1) * (swW * 0.115);
      final Offset kc = Offset(kx, swH * 0.34);
      canvas.drawCircle(
        kc,
        swH * 0.086,
        HighResShaders.brushedMetalShader != null
            ? (Paint()..isAntiAlias = true..shader = HighResShaders.brushedMetalShader)
            : (Paint()..isAntiAlias = true..color = const Color(0xFF94A3B8)),
      );
      canvas.drawCircle(kc, swH * 0.072, Paint()..isAntiAlias = true..color = knobColors[k]);
      canvas.drawCircle(kc, swH * 0.032, Paint()..isAntiAlias = true..color = const Color(0xFF13171F));
    }

    // Illuminated Tactile Side Buttons
    _drawWheelButton(canvas, Offset(-swW * 0.33, -swH * 0.24), const Color(0xFF29B6F6));
    _drawWheelButton(canvas, Offset(swW * 0.33, -swH * 0.24), const Color(0xFFFFCA28));
    _drawWheelButton(canvas, Offset(-swW * 0.31, -swH * 0.04), const Color(0xFFEF5350));
    _drawWheelButton(canvas, Offset(swW * 0.31, -swH * 0.04), const Color(0xFF66BB6A));
    _drawWheelButton(canvas, Offset(-swW * 0.29, swH * 0.16), const Color(0xFFAB47BC));
    _drawWheelButton(canvas, Offset(swW * 0.29, swH * 0.16), const Color(0xFFFF7043));

    // Contoured Multi-Shaded Racing Gloves
    _drawRacingGloveUltra(canvas, swW, swH, true);
    _drawRacingGloveUltra(canvas, swW, swH, false);

    canvas.restore();
  }

  void _drawWheelButton(Canvas canvas, Offset center, Color color) {
    canvas.drawCircle(center, 6.4, Paint()..isAntiAlias = true..color = const Color(0xFF0D1016));
    canvas.drawCircle(center, 4.6, Paint()..isAntiAlias = true..color = color);
    canvas.drawCircle(Offset(center.dx - 1.3, center.dy - 1.3), 1.5, Paint()..isAntiAlias = true..color = const Color(0xAAFFFFFF));
  }

  void _drawRacingGloveUltra(Canvas canvas, double swW, double swH, bool isLeft) {
    final double s = isLeft ? -1.0 : 1.0;
    final Rect palmRect = Rect.fromCenter(
      center: Offset(s * swW * 0.45, swH * 0.16),
      width: swW * 0.23,
      height: swH * 0.64,
    );
    final Paint gloveShader = Paint()
      ..isAntiAlias = true
      ..shader = LinearGradient(
        begin: isLeft ? Alignment.centerLeft : Alignment.centerRight,
        end: isLeft ? Alignment.centerRight : Alignment.centerLeft,
        colors: [
          Color.lerp(livery.gloveColor, Colors.black, 0.38)!,
          livery.gloveColor,
          Color.lerp(livery.gloveColor, Colors.white, 0.18)!,
        ],
      ).createShader(palmRect);

    canvas.drawRRect(RRect.fromRectAndRadius(palmRect, const Radius.circular(20)), gloveShader);

    // Thumb wrapped over upper grip
    final RRect thumb = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(s * swW * 0.36, -swH * 0.02), width: swW * 0.135, height: swH * 0.195),
      const Radius.circular(10),
    );
    canvas.drawRRect(thumb, gloveShader);
    canvas.drawRRect(
      thumb,
      Paint()
        ..isAntiAlias = true
        ..color = const Color(0x55000000)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.6,
    );

    // Knuckle seam & wrist cuff stripe
    canvas.drawLine(
      Offset(s * swW * 0.41, swH * 0.04),
      Offset(s * swW * 0.49, swH * 0.24),
      Paint()..isAntiAlias = true..color = const Color(0x3DFFFFFF)..strokeWidth = 1.9,
    );
    canvas.drawLine(
      Offset(s * swW * 0.37, swH * 0.36),
      Offset(s * swW * 0.53, swH * 0.36),
      Paint()..isAntiAlias = true..color = livery.secondary.withAlpha(170)..strokeWidth = 2.6,
    );
  }

  void _drawChaseCarUltra(Canvas canvas, double w, double h) {
    canvas.save();
    canvas.translate(w * 0.5, h * 0.80);
    canvas.rotate(steerAngle * 0.06 + spinYaw * 0.45);

    canvas.drawOval(
      Rect.fromCenter(center: const Offset(0, 14), width: 184, height: 28),
      Paint()
        ..color = const Color(0xC0000000)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 7),
    );
    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-82, -24, 29, 45), const Radius.circular(6)), Paint()..isAntiAlias = true..color = const Color(0xFF13161C));
    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(53, -24, 29, 45), const Radius.circular(6)), Paint()..isAntiAlias = true..color = const Color(0xFF13161C));
    canvas.drawRect(const Rect.fromLTWH(-46, 2, 92, 14), Paint()..color = const Color(0xFF1A1E26));

    final Path body = Path()
      ..moveTo(-55, 4)
      ..lineTo(-35, -42)
      ..lineTo(35, -42)
      ..lineTo(55, 4)
      ..close();
    canvas.drawPath(
      body,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [livery.primaryLight, livery.primary, livery.primaryDark],
        ).createShader(const Rect.fromLTWH(-55, -42, 110, 46)),
    );

    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-12, -54, 24, 24), const Radius.circular(10)), Paint()..isAntiAlias = true..color = const Color(0xFF1A1D24));
    canvas.drawRect(const Rect.fromLTWH(-4, -2, 8, 10), Paint()..color = const Color(0xFFFF1744));
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(-60, ersActive ? -50 : -42, 120, ersActive ? 7 : 12), const Radius.circular(3)),
      Paint()..isAntiAlias = true..color = ersActive ? const Color(0xFF00E5FF) : livery.secondary,
    );
    canvas.restore();
  }

  void _drawCenteredText(Canvas canvas, String text, Offset center, double fontSize, Color color, FontWeight weight) {
    final TextPainter tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(color: color, fontSize: fontSize, fontWeight: weight),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(center.dx - tp.width * 0.5, center.dy - tp.height * 0.5));
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}
